inbound.set-body:
@{
            var body = context.Request.Body.As();

            // Only include properties that were provided in the request so unspecified fields aren't overwritten
            var movie = new JObject();
            addPropertyToMovieIfProvided("title", "Title");
            addPropertyToMovieIfProvided("description", "Description");
            addPropertyToMovieIfProvided("year", "Year");
            addPropertyToMovieIfProvided("rating", "Rating");

            return movie.ToString(Newtonsoft.Json.Formatting.None);

            void addPropertyToMovieIfProvided(string sourcePropertyName, string targetPropertyName)
            {
                if (body[sourcePropertyName] != null)
                {
                    movie[targetPropertyName] = body[sourcePropertyName];
                }
            }
        }
